import React, { useState } from 'react';

export default function App() {
  const [count, setCount] = useState(0);

  return (
    <div className="min-h-screen bg-slate-900 text-white p-8 flex flex-col items-center justify-center">
      <h1 className="text-4xl font-bold mb-4">AI Orchestrated SaaS App</h1>
      <p className="text-slate-400 mb-6">Add chart widget</p>
      <button 
        onClick={() => setCount(c => c + 1)}
        className="px-6 py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-semibold transition-all shadow-lg"
      >
        Clicked {count} times
      </button>
    </div>
  );
}

